class Battle::Move::OHKO < Battle::Move::FixedDamageMove
  def pbFailsAgainstTarget?(user, target, show_message)
    if target.level > user.level
      @battle.pbDisplay(_INTL("{1} is unaffected!", target.pbThis)) if show_message
      return true
    end
    if target.hasActiveAbility?(:STURDY) && !@battle.moldBreaker
      if show_message
        @battle.pbShowAbilitySplash(target)
        if Battle::Scene::USE_ABILITY_SPLASH
          @battle.pbDisplay(_INTL("But it failed to affect {1}!", target.pbThis(true)))
        else
          @battle.pbDisplay(_INTL("But it failed to affect {1} because of its {2}!",
                                  target.pbThis(true), target.abilityName))
        end
        @battle.pbHideAbilitySplash(target)
      end
      return true
    end
    return false
  end

  def pbAccuracyCheck(user, target)
    acc = @accuracy + user.level - target.level
    return @battle.pbRandom(100) < acc
  end

  def pbFixedDamage(user, target)
    return target.totalhp
  end

  def pbHitEffectivenessMessages(user, target, numTargets = 1)
    super
    @battle.pbDisplay(_INTL("It's a one-hit KO!")) if target.fainted?
  end
end

class Battle::Move::AttackerFaintsIfUserFaints < Battle::Move
  def pbMoveFailed?(user, targets)
    if Settings::MECHANICS_GENERATION >= 7 && user.effects[PBEffects::DestinyBondPrevious]
      @battle.pbDisplay(_INTL("But it failed!"))
      return true
    end
    return false
  end

  def pbEffectGeneral(user)
    user.effects[PBEffects::DestinyBond] = true
    @battle.pbDisplay(_INTL("{1} is hoping to take its attacker down with it!", user.pbThis))
  end
end

def pbFindTargets(choice, move, user)
  preTarget = choice[3]   # A target that was already chosen
  targets = []
  # Get list of targets
  case move.pbTarget(user).id   # Curse can change its target type
  when :NearAlly
    targetBattler = (preTarget >= 0) ? @battle.battlers[preTarget] : nil
    if !pbAddTarget(targets, user, targetBattler, move)
      pbAddTargetRandomAlly(targets, user, move)
    end
  when :UserOrNearAlly
    targetBattler = (preTarget >= 0) ? @battle.battlers[preTarget] : nil
    if !pbAddTarget(targets, user, targetBattler, move, true, true)
      pbAddTarget(targets, user, user, move, true, true)
    end
  when :AllAllies
    @battle.allSameSideBattlers(user.index).each do |b|
      pbAddTarget(targets, user, b, move, false, true) if b.index != user.index
    end
  when :UserAndAllies
    pbAddTarget(targets, user, user, move, true, true)
    @battle.allSameSideBattlers(user.index).each { |b| pbAddTarget(targets, user, b, move, false, true) }
  when :NearFoe, :NearOther
    targetBattler = (preTarget >= 0) ? @battle.battlers[preTarget] : nil
    if !pbAddTarget(targets, user, targetBattler, move)
      if preTarget >= 0 && !user.opposes?(preTarget)
        pbAddTargetRandomAlly(targets, user, move)
      else
        pbAddTargetRandomFoe(targets, user, move)
      end
    end
  when :RandomNearFoe
    pbAddTargetRandomFoe(targets, user, move)
  when :AllNearFoes
    @battle.allOtherSideBattlers(user.index).each { |b| pbAddTarget(targets, user, b, move) }
  when :Foe, :Other
    targetBattler = (preTarget >= 0) ? @battle.battlers[preTarget] : nil
    if !pbAddTarget(targets, user, targetBattler, move, false)
      if preTarget >= 0 && !user.opposes?(preTarget)
        pbAddTargetRandomAlly(targets, user, move, false)
      else
        pbAddTargetRandomFoe(targets, user, move, false)
      end
    end
  when :AllFoes
    @battle.allOtherSideBattlers(user.index).each { |b| pbAddTarget(targets, user, b, move, false) }
  when :AllNearOthers
    @battle.allBattlers.each { |b| pbAddTarget(targets, user, b, move) }
  when :AllBattlers
    @battle.allBattlers.each { |b| pbAddTarget(targets, user, b, move, false, true) }
  else
    # Used by Counter/Mirror Coat/Metal Burst/Bide
    move.pbAddTarget(targets, user)   # Move-specific pbAddTarget, not the def below
  end
  return targets
end

def initialize(battle, move)
  @battle        = battle
  @realMove      = move
  @id            = move.id
  @name          = move.name   # Get the move's name
  # Get data on the move
  @function_code = move.function_code
  @power         = move.power
  @type          = move.type
  @category      = move.category
  @accuracy      = move.accuracy
  @pp            = move.pp   # Can be changed with Mimic/Transform
  @target        = move.target
  @priority      = move.priority
  @flags         = move.flags.clone
  @addlEffect    = move.effect_chance
  @powerBoost    = false   # For Aerilate, Pixilate, Refrigerate, Galvanize
  @snatched      = false
end

def self.from_pokemon_move(battle, move)
  validate move => Pokemon::Move
  code = move.function_code || "None"
  if code[/^\d/]   # Begins with a digit
    class_name = sprintf("Battle::Move::Effect%s", code)
  else
    class_name = sprintf("Battle::Move::%s", code)
  end
  if Object.const_defined?(class_name)
    return Object.const_get(class_name).new(battle, move)
  end
  return Battle::Move::Unimplemented.new(battle, move)
end

GameData::Target.register({
  :id               => :User,
  :name             => _INTL("User")
})

def self.triggerDamageCalcFromUser(item, user, target, move, mults, power, type)
  DamageCalcFromUser.trigger(item, user, target, move, mults, power, type)
end

def self.triggerDamageCalcFromTarget(item, user, target, move, mults, power, type)
  DamageCalcFromTarget.trigger(item, user, target, move, mults, power, type)
end

def isSpecies?(species)
  return @pokemon&.isSpecies?(species)
end

def abilityActive?(ignore_fainted = false, check_ability = nil)
  return false if fainted? && !ignore_fainted
  return false if @effects[PBEffects::GastroAcid]
  return false if check_ability != :NEUTRALIZINGGAS && self.ability != :NEUTRALIZINGGAS &&
                  @battle.pbCheckGlobalAbility(:NEUTRALIZINGGAS)
  return true
end

def hasActiveAbility?(check_ability, ignore_fainted = false)
  return false if !abilityActive?(ignore_fainted, check_ability)
  return check_ability.include?(@ability_id) if check_ability.is_a?(Array)
  return self.ability == check_ability
end
alias hasWorkingAbility hasActiveAbility?

def itemActive?(ignoreFainted = false)
  return false if fainted? && !ignoreFainted
  return false if @effects[PBEffects::Embargo] > 0
  return false if @battle.field.effects[PBEffects::MagicRoom] > 0
  return false if @battle.corrosiveGas[@index % 2][@pokemonIndex]
  return false if hasActiveAbility?(:KLUTZ, ignoreFainted)
  return true
end

def hasActiveItem?(check_item, ignore_fainted = false)
  return false if !itemActive?(ignore_fainted)
  return check_item.include?(@item_id) if check_item.is_a?(Array)
  return self.item == check_item
end

class HandlerHashSymbol
  def initialize
    @hash    = {}
    @add_ifs = {}
  end

  def [](sym)
    sym = sym.id if !sym.is_a?(Symbol) && sym.respond_to?("id")
    return @hash[sym] if sym && @hash[sym]
    @add_ifs.each_value do |add_if|
      return add_if[1] if add_if[0].call(sym)
    end
    return nil
  end

  def add(sym, handler = nil, &handlerBlock)
    if ![Proc, Hash].include?(handler.class) && !block_given?
      raise ArgumentError, "#{self.class.name} for #{sym.inspect} has no valid handler (#{handler.inspect} was given)"
    end
    @hash[sym] = handler || handlerBlock if sym
  end

  def addIf(sym, conditionProc, handler = nil, &handlerBlock)
    if ![Proc, Hash].include?(handler.class) && !block_given?
      raise ArgumentError, "addIf call for #{sym} in #{self.class.name} has no valid handler (#{handler.inspect} was given)"
    end
    @add_ifs[sym] = [conditionProc, handler || handlerBlock]
  end

  def copy(src, *dests)
    handler = self[src]
    return if !handler
    dests.each { |dest| add(dest, handler) }
  end

  def remove(key)
    @hash.delete(key)
  end

  def clear
    @hash.clear
    @add_ifs.clear
  end

  def trigger(sym, *args)
    sym = sym.id if !sym.is_a?(Symbol) && sym.respond_to?("id")
    handler = self[sym]
    return handler&.call(sym, *args)
  end
end
